// Test mode: when started from the Manual Run trigger, run only one
// Indeed search and one Yelp search with a 5-item cap each.
let testMode = false;
try { $('Manual Run').first(); testMode = true; } catch (e) {}
if (testMode) {
  // URGENT one-off run (2026-09-24): Maps branch only, all 18 contractor terms
  // for ONE location per execution (max 30 places/search). LOC_INDEX per run.
  const urgentTerms = ['general contractor', 'home remodeling', 'roofing contractor', 'HVAC contractor', 'kitchen remodeling', 'bathroom remodeling', 'basement finishing', 'deck builder', 'fence contractor', 'concrete contractor', 'masonry contractor', 'paving contractor', 'excavation contractor', 'siding contractor', 'plumbing contractor', 'electrical contractor', 'painting contractor', 'flooring contractor'];
  const LOCATIONS = ['Fredericksburg VA', 'Stafford VA', 'Spotsylvania VA', 'King George VA', 'Culpeper VA', 'Warrenton VA', 'Woodbridge VA', 'Manassas VA'];
  const LOC_INDEX = 0;
  const loc = LOCATIONS[LOC_INDEX];
  // ONE-SEARCH live test mode (restore target): single term, single location.
  const SINGLE_TEST = false;
  if (SINGLE_TEST) {
    return [{ json: { branch: 'maps', searchTerm: 'roofing contractor', location: 'Fredericksburg VA', maxItems: 30 } }];
  }
  // Full run: all 18 contractor terms for ONE location (LOC_INDEX), each
  // executed as its own async Apify run, one at a time.
  return urgentTerms.map(t => ({ json: { branch: 'maps', searchTerm: t, location: loc, maxItems: 30 } }));
}
const out = [];
const positions = ['receptionist', 'front desk', 'dispatcher', 'office manager'];
const jobLocations = ['Fredericksburg, VA', 'Manassas, VA'];
for (const p of positions) {
  for (const l of jobLocations) {
    out.push({ json: { branch: 'jobs', position: p, location: l } });
  }
}
// Maps: rotating slice of the term x city matrix. The offset persists in
// workflow static data so each run continues where the last stopped; when the
// full matrix is done it wraps and starts over. Cap: 1500 Maps places per run.
const MAPS_PER_SEARCH = 40;
const MAPS_RUN_CAP = 1500;
const mapsTerms = ['general contractor', 'home remodeling', 'roofing contractor', 'HVAC contractor', 'kitchen remodeling', 'bathroom remodeling', 'basement finishing', 'deck builder', 'fence contractor', 'concrete contractor', 'masonry contractor', 'paving contractor', 'excavation contractor', 'siding contractor', 'plumbing contractor', 'electrical contractor', 'painting contractor', 'flooring contractor'];
const mapsLocations = ['Fredericksburg VA', 'Stafford VA', 'Spotsylvania VA', 'King George VA', 'Culpeper VA', 'Warrenton VA', 'Woodbridge VA', 'Manassas VA', 'Dumfries VA', 'Leesburg VA', 'Sterling VA', 'Herndon VA', 'Chantilly VA', 'Fairfax VA', 'Springfield VA', 'Alexandria VA', 'Orange VA', 'Louisa VA', 'Bowling Green VA', 'Ashland VA', 'Front Royal VA'];
const matrix = [];
for (const t of mapsTerms) for (const l of mapsLocations) matrix.push({ t, l });
const sd = $getWorkflowStaticData('global');
let offset = typeof sd.matrixOffset === 'number' ? sd.matrixOffset : 0;
if (offset >= matrix.length) offset = 0;
const maxSearches = Math.floor(MAPS_RUN_CAP / MAPS_PER_SEARCH);
let used = 0;
let mi = offset;
while (used < maxSearches) {
  const m = matrix[mi % matrix.length];
  out.push({ json: { branch: 'maps', searchTerm: m.t, location: m.l, maxItems: MAPS_PER_SEARCH } });
  used++;
  mi++;
}
sd.matrixOffset = (offset + used) % matrix.length;
// Yelp branch (unchanged budget): fills up to 600 results after Maps.
const TOTAL_MAX_RESULTS = 600;
let usedResults = 0;
const yelpTerms = ['general contractor', 'home remodeling', 'roofing', 'HVAC', 'kitchen and bath remodeling', 'basement finishing', 'handyman', 'plumbing', 'electrician', 'painting contractor', 'deck builder', 'fence contractor', 'concrete contractor', 'flooring contractor'];
const yelpLocations = ['Fredericksburg VA', 'Stafford VA', 'Spotsylvania VA', 'King George VA', 'Culpeper VA', 'Woodbridge VA', 'Manassas VA'];
outerYelp:
for (const t of yelpTerms) {
  for (const l of yelpLocations) {
    const per = Math.min(15, TOTAL_MAX_RESULTS - usedResults);
    if (per <= 0) break outerYelp;
    usedResults += per;
    out.push({ json: { branch: 'yelp', searchTerm: t, location: l, maxItems: per } });
  }
}
return out;

