// Prefilter (shared with Yelp): listed_website empty or only a
// social/directory domain, 10+ reviews, rating >= 3.8, not permanently closed,
// category is a trade. Surviving candidates go to the Verification tab.
const fakeSiteRe = /facebook\.com|instagram\.com|yelp\.com|nextdoor\.com|linktr\.ee|sites\.google\.com|business\.site|angi\.com|homeadvisor\.com|thumbtack\.com|houzz\.com|bbb\.org/i;
const beautyRe = /salon|spa|nail|beauty|massage|barber|lash|med spa|tanning/i;
const tradeRe = /contractor|handyman|remodel|roof|siding|gutter|window|hvac|plumb|electric|paint|drywall|floor|tile|deck|fenc|concrete|masonry|paving|excavat|landscap|hardscap|tree|pressure wash|garage door|insulat|waterproof|builder|construction|home improvement|carpent|kitchen|bath|basement/i;
const items = $input.all().filter(i => Object.keys(i.json).length > 0);
const out = [];
for (const item of items) {
  const j = item.json;
  const name = j.title || j.name || '';
  if (!name) continue;
  if (j.permanentlyClosed === true) {
    console.log('DROPPED Maps lead (permanently closed): "' + name + '"');
    continue;
  }
  const category = j.categoryName || '';
  if (beautyRe.test(category) || beautyRe.test(name)) {
    console.log('DROPPED Maps lead (beauty/salon category): "' + name + '" — category: ' + category);
    continue;
  }
  if (!tradeRe.test(category)) {
    console.log('DROPPED Maps lead (not a trade): "' + name + '" — category: ' + category);
    continue;
  }
  const reviews = j.reviewsCount != null ? Number(j.reviewsCount) : null;
  const rating = j.totalScore != null ? Number(j.totalScore) : null;
  if (reviews == null || !isFinite(reviews)) {
    console.log('DROPPED Maps lead (no review count): "' + name + '"');
    continue;
  }
  if (reviews < 10 || rating == null || !isFinite(rating) || rating < 3.8) {
    console.log('DROPPED Maps lead (below quality threshold): "' + name + '" — rating: ' + rating + ', reviews: ' + reviews);
    continue;
  }
  const website = String(j.website || '').trim();
  if (website && !fakeSiteRe.test(website)) {
    console.log('DROPPED Maps lead (has a real website): "' + name + '" — ' + website);
    continue;
  }
  const stripPhone = (ph) => {
    let d = String(ph || '').replace(/\D/g, '');
    if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
    return d;
  };
  // Google Business Profile booking/reservation/order/menu/appointment links.
  const gbp = [];
  if (j.menuUrl) gbp.push(j.menuUrl);
  if (j.reserveTableUrl) gbp.push(j.reserveTableUrl);
  if (Array.isArray(j.orderOnlineLinks)) for (const l of j.orderOnlineLinks) gbp.push(typeof l === 'string' ? l : (l.url || ''));
  if (Array.isArray(j.bookingLinks)) for (const l of j.bookingLinks) gbp.push(typeof l === 'string' ? l : (l.url || ''));
  if (j.appointmentUrl) gbp.push(j.appointmentUrl);
  // Address fields: use the actor's address/city/state/url fields, then fall
  // back to parsing the city out of the address string, then to the searched
  // location name, so city is never blank.
  const address = String(j.address || j.street || '').trim();
  let city = String(j.city || '').trim();
  if (!city && address) {
    const parts = address.split(',').map(s => s.trim()).filter(Boolean);
    if (parts.length >= 2) city = parts[parts.length >= 3 ? parts.length - 2 : parts.length - 1].replace(/s+VA .*$/i, '').trim();
  }
  if (!city) {
    let searchedLoc = '';
    try { searchedLoc = $('Route Branch').item.json.location || ''; } catch (e) {}
    city = String(searchedLoc).replace(/s+VA .*$/i, '').replace(/,.*$/, '').trim();
  }
  out.push({ json: {
    business_name: name,
    category,
    owner: '',
    city,
    state: String(j.state || 'VA').trim() || 'VA',
    address,
    phone: stripPhone(j.phone || j.phoneUnformatted || ''),
    email: j.email || '',
    website,
    listed_website: website,
    maps_url: j.url || '',
    gbp_links: gbp.filter(Boolean).join(' '),
    rating: rating != null ? String(rating) : '',
    reviews: reviews != null ? String(reviews) : '',
    source: 'maps',
  } });
}
return out;

const stripPhone = (p) => {
  let d = String(p || '').replace(/\D/g, '');
  if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
  return d;
};
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const j = item.json;
  if (Object.keys(j).length === 0) continue;
  const nameKey = String(j.business_name || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const phoneKey = stripPhone(j.phone);
