const stripPhone = (p) => {
  let d = String(p || '').replace(/\D/g, '');
  if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
  return d;
};
const normName = (n) => String(n || '').toLowerCase().replace(/\s+/g, ' ').trim();
const normCity = (c) => String(c || '').toLowerCase().replace(/\s+/g, ' ').trim();
const namePhone = new Set();
const phones = new Set();
const nameCity = new Set();
const emails = new Set();
let verification = [];
try { verification = $('Read Verification Tab').all(); } catch (e) {}
const leads = $('Read Leads Tab').all();
const calls = $('Read Call List Tab').all();
for (const row of [...leads, ...calls, ...verification]) {
  const j = row.json;
  const nk = normName(j.business_name);
  const pk = stripPhone(j.phone);
  const ck = normCity(j.city);
  if (nk && pk) namePhone.add(nk + '|' + pk);
  if (pk) phones.add(pk);
  if (nk && ck) nameCity.add(nk + '|' + ck);
  const ek = String(j.email || '').toLowerCase().trim();
  if (ek) emails.add(ek);
}
// Scraped items come from Add Dedupe Keys — the two sheet reads above replace
// this node's own input with sheet rows, so $input cannot be used here.
const out = [];
for (const item of $('Add Dedupe Keys').all()) {
  const j = item.json;
  if (Object.keys(j).length === 0) continue;
  const src = j.source;
  if (src === 'maps' || src === 'yelp') {
    // Verification candidates: dedupe by phone digits and by lowercased name+city.
    if (j.phoneKey && phones.has(j.phoneKey)) { item.json.skip_reason = 'duplicate phone'; continue; }
    const ck = normCity(j.city);
    if (j.nameKey && ck && nameCity.has(j.nameKey + '|' + ck)) { item.json.skip_reason = 'duplicate name+city'; continue; }
  } else {
    if (j.emailKey && emails.has(j.emailKey)) { item.json.skip_reason = 'duplicate email'; continue; }
    if (j.nameKey && j.phoneKey && namePhone.has(j.nameKey + '|' + j.phoneKey)) { item.json.skip_reason = 'duplicate name+phone'; continue; }
  }
  item.json.skip_reason = '';
  out.push(item);
}
return out;

// Maps and Yelp leads never reach here (they have no real website by the keep
// rule), but belt-and-braces: skip website contact-scraping for them — there is
// no site to crawl. Also cap enrichment at 10 websites on manual test runs.
let testMode = false;
try { $('Manual Run').first(); testMode = true; } catch (e) {}
const items = $input.all().filter(i => i.json.source === 'indeed');
return testMode ? items.slice(0, 10) : items;

