const out = [];
for (const item of items) {
  const j = item.json;
  const name = j.name || j.businessName || '';
  if (!name) continue;
  let category = '';
  if (Array.isArray(j.categories) && j.categories.length) {
    const c = j.categories[0];
    category = typeof c === 'string' ? c : (c.title || '');
  } else if (typeof j.category === 'string') category = j.category;
  const allCats = Array.isArray(j.categories) ? j.categories.map(c => typeof c === 'string' ? c : (c.title || '')).join(' ') : category;
